import {useEffect,useRef,useState,type ReactNode} from 'react';
import './shell.css';
export function ApplicationShell({workspace,inspector}:{workspace:ReactNode;inspector:ReactNode}) {
 const [width,setWidth]=useState(320),[pane,setPane]=useState('workspace');
 const [section,setSection]=useState('Inbox'); const drag=useRef<number|null>(null);
 useEffect(()=>{try{const n=Number(localStorage.getItem('inspector-width'));if(n>=240&&n<=480)setWidth(n)}catch{}},[]);
 function resize(n:number){const next=Math.max(240,Math.min(480,n));setWidth(next);try{localStorage.setItem('inspector-width',String(next))}catch{}}
 return <div className="shell" style={{'--inspector-width':width+'px'} as React.CSSProperties}>
 <a className="skip" href="#workspace">Skip to workspace</a>
 <header className="shell-toolbar"><strong>Workspace</strong><div className="phone-switch" aria-label="Visible pane">{['navigation','workspace','inspector'].map(p=><button key={p} aria-pressed={pane===p} onClick={()=>setPane(p)}>{p}</button>)}</div></header>
 <div className="shell-body">
 <nav aria-label="Main navigation" className="shell-nav scroll-pane" data-active={pane==='navigation'}>{[['Work','Inbox','Projects'],['Library','Archive','Templates']].map(([heading,...items])=><section key={heading}><h2>{heading}</h2>{items.map(item=><button key={item} aria-current={section===item?'page':undefined} onClick={()=>{setSection(item);setPane('workspace')}}>{item}</button>)}</section>)}</nav>
 <main id="workspace" tabIndex={-1} className="scroll-pane workspace" data-active={pane==='workspace'}><h1>{section}</h1>{workspace}</main>
 <div className="resize" role="separator" tabIndex={0} aria-label="Inspector width" aria-orientation="vertical" aria-valuemin={240} aria-valuemax={480} aria-valuenow={width} onKeyDown={e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();resize(e.key==='Home'?240:e.key==='End'?480:width+(e.key==='ArrowLeft'?16:-16))}}} onPointerDown={e=>{drag.current=e.clientX;e.currentTarget.setPointerCapture(e.pointerId)}} onPointerMove={e=>{if(drag.current!==null){resize(width+drag.current-e.clientX);drag.current=e.clientX}}} onPointerUp={()=>drag.current=null} onPointerCancel={()=>drag.current=null}/>
 <aside aria-label="Inspector" className="scroll-pane inspector" data-active={pane==='inspector'}>{inspector}</aside>
 </div></div>;
}
